const b = $input.first().json.body || $input.first().json || {};
const hist = Array.isArray(b.history) ? b.history.filter(h => h && h.text).slice(-4) : [];
return [{ json: { text: (b.text || '').toString().slice(0, 2000),
  userId: (b.userId || '').toString(), history: hist } }];

const p = $('Prep').first().json;
const q = (p.text || '').toString();
let need_sql = false, kind = 'rag';
if (q.trim()) {
  const hasCode = /SD-?\d{3,}/i.test(q);
  const hasPhone = /0\d[\d\- ]{7,}/.test(q);
  const liveKw = /(ราคา|สต็อก|สต๊อก|คงเหลือ|เหลือ|ออเดอร์|คำสั่งซื้อ|พัสดุ|สถานะ|จัดส่ง|โอน|ชำระ|คูปอง|ส่วนลด|ขายแล้ว|บาท|สินค้า|รุ่น|สี|ไซส์)/.test(q);
  const recKw = /(แนะนำ|เปรียบเทียบ|เปรียบ|คุ้ม|ดีไหม|เลือก|ตัวไหน|รุ่นไหน|ดีกว่า)/.test(q);
  const trackKw = /(เหลือ|คงเหลือ|สถานะ|ออเดอร์|พัสดุ|เช็ค|เช็ก|ติดตาม|มีของ|หมด)/.test(q);
  const chitchat = /^(สวัสดี|หวัดดี|ดีครับ|ดีค่ะ|hello|hi|hey|ขอบคุณ|ขอบใจ|ลาก่อน|บ๊ายบาย|bye|โอเค|ตกลง|ทดสอบ|test|เทส)[\s!?ครับค่ะคะ]*$/i.test(q.trim());
  if (hasCode || hasPhone || trackKw) { need_sql = true; kind = 'lookup'; }
  else if (liveKw || recKw) { need_sql = true; kind = 'both'; }
  else if (!chitchat) { need_sql = true; kind = 'both'; }
}
return [{ json: { need_sql, kind, t0: Date.now() } }];

const p = $('Prep').first().json;
const t = (p.text || '').toString().trim();
const out = (sql) => [{ json: { sql_raw: sql } }];
let m = t.match(/\b(SD-?[A-Za-z0-9]{3,})\b/i);
if (m) {
  const code = m[1].replace(/-/g, '').toUpperCase();
  return out("SELECT o.code,o.total,o.status,o.created_at,i.name,i.qty,i.price FROM shop_orders o"
    + " LEFT JOIN shop_order_items i ON i.order_id=o.id WHERE REPLACE(UPPER(o.code),'-','')='" + code.replace(/'/g, "''") + "' LIMIT 50");
}
m = t.match(/0\d[\d\- ]{7,}/);
if (m) {
  const digits = m[0].replace(/\D/g, '').slice(0, 10);
  if (digits.length >= 9) return out("SELECT code,total,status,created_at FROM shop_orders WHERE cust_phone LIKE '%" + digits + "%' ORDER BY id DESC LIMIT 5");
}
let cap = null;
const bm = t.match(/ไม่เกิน\s*([\d,]+)/);
if (bm) cap = parseInt(bm[1].replace(/,/g, ''), 10);
let s = t;
['เท่าไร','เท่าไหร่','ราคา','สต็อก','สต๊อก','เหลือ','คงเหลือ','สถานะ','ออเดอร์','คำสั่งซื้อ','พัสดุ','เช็ค','เช็ก','ติดตาม','แนะนำ','เปรียบเทียบ','คุ้ม','หรือไม่','ดีไหม','ตัวไหน','รุ่นไหน','ดีกว่า','บาท','ไหม','มั้ย','ครับ','ค่ะ','คะ','อะไร','ยังไง','อย่างไร','กี่ชิ้น','ชิ้น','ขอทราบ','ขอถาม','อยากทราบ','ทราบ','ช่วยหา','ช่วย'].forEach(w => { s = s.split(w).join(' '); });
if (bm) s = s.replace(bm[0], ' ');
const STOP = new Set(['ที่','และ','กับ','ของ','ใน','คือ','มี','หรือ','ๆ','ตัว','รุ่น','สี','ไซส์','อัน','เลข','เบอร์','รหัส','อันไหน','แบบ','อยาก','ได้','ให้','หน่อย','ขอดู','ทั้งหมด','หา','ถาม','เท่า','กี่']);
const SYN = {'มือถือ':['มือถือ','สมาร์ทโฟน','โทรศัพท์'],'จอ':['จอ','มอนิเตอร์','Monitor'],'มอนิเตอร์':['มอนิเตอร์','จอ','Monitor'],'หูฟัง':['หูฟัง','True Wireless'],'นาฬิกา':['นาฬิกา','Watch','สมาร์ทวอทช์'],'แล็ปท็อป':['แล็ปท็อป','โน้ตบุ๊ก','Laptop','Notebook'],'โน้ตบุ๊ก':['โน้ตบุ๊ก','แล็ปท็อป','Laptop'],'แท็บเล็ต':['แท็บเล็ต','Tablet'],'กล้อง':['กล้อง','Camera','เว็บแคม'],'คีย์บอร์ด':['คีย์บอร์ด','Keyboard'],'เมาส์':['เมาส์','Mouse'],'ลำโพง':['ลำโพง','Speaker'],'พัดลม':['พัดลม','Fan'],'แอร์':['แอร์','เครื่องปรับอากาศ'],'ทีวี':['ทีวี','TV'],'ตู้เย็น':['ตู้เย็น'],'รองเท้า':['รองเท้า','ผ้าใบ','Sneaker'],'กระเป๋า':['กระเป๋า'],'เสื้อ':['เสื้อ','Shirt'],'กางเกง':['กางเกง','ยีนส์']};
const toks = [];
s.split(/\s+/).forEach(tok => {
  tok = tok.replace(/^[ \t\n\r"'.,:;!?()\[\]]+|[ \t\n\r"'.,:;!?()\[\]]+$/g, '');
  if (!tok || STOP.has(tok) || tok.length < 2 || toks.length >= 4) return;
  toks.push(tok);
});
if (!toks.length && !(cap > 0)) return out('');
const esc = (x) => String(x).replace(/'/g, "''").replace(/\\/g, '');
const where = ['is_active=TRUE'];
toks.forEach(tok => {
  if (/^\d+$/.test(tok)) {
    where.push("(name ~* '(^|[^0-9])" + tok + "([^0-9]|$)')");
  } else {
    const alts = SYN[tok] || [tok];
    where.push('(' + alts.map(a => "name ILIKE '%" + esc(a) + "%'" ).join(' OR ') + ')');
  }
});
if (cap > 0) where.push('price<=' + cap);
return out('SELECT sku,name,price,old_price,stock,shop_name,image_url FROM shop_products WHERE ' + where.join(' AND ') + ' ORDER BY sold DESC LIMIT 10');

const prep = $('Prep').first().json;
const r = $('Route SQL').first().json;
const allow = ['shop_products','shop_orders','shop_order_items'];
const esc = (s) => (s || '').toString().replace(/'/g, "''");
const ms = Date.now() - (r.t0 || Date.now());
const aq = (ok, sql, rows, err) => `INSERT INTO ai_sql_audit(channel,user_ref,question,route,sql,rows,ms,ok,err) VALUES ('shop','${esc(prep.userId)}','${esc((prep.text || '').slice(0, 500))}','${r.kind || 'rag'}','${esc((sql || '').slice(0, 2000))}',${rows},${ms},${ok ? 'TRUE' : 'FALSE'},'${esc((err || '').slice(0, 300))}') RETURNING id`;
const fail = (reason) => [{ json: { valid: false, sql: '', used: [], reason, audit_sql: aq(false, '', 0, reason) } }];
let raw = '';
try { raw = (($input.first().json.sql_raw) || '').toString(); } catch(e) {}
raw = raw.replace(/```sql|```/gi, '').trim().replace(/;+\s*$/, '');
if (!/^SELECT\b/i.test(raw)) return fail('not-select');
const up = raw.toUpperCase();
for (const b of [';', '--', '/*', '*/', 'PG_']) { if (up.indexOf(b) >= 0) return fail('forbidden:' + b); }
for (const b of ['UNION','INSERT','UPDATE','DELETE','DROP','CREATE','ALTER','TRUNCATE','COPY','GRANT','REVOKE','INFORMATION_SCHEMA']) {
  if (new RegExp('\\b' + b + '\\b', 'i').test(raw)) return fail('forbidden:' + b);
}
const used = [...raw.matchAll(/\b(?:FROM|JOIN)\s+"?([A-Za-z_][\w$]*)"?/gi)].map(m => m[1].toLowerCase());
if (!used.length || !used.every(t => allow.indexOf(t) >= 0)) return fail('bad-table');
const orderTbl = used.indexOf('shop_orders') >= 0 || used.indexOf('shop_order_items') >= 0;
if (orderTbl && !/(code|cust_phone|order_id)/i.test(raw)) return fail('order-needs-key');
if (used.indexOf('shop_products') >= 0 && !/is_active/i.test(raw)) return fail('needs-is_active');
let sql = raw;
const m = sql.match(/LIMIT\s+(\d+)/i);
if (!m) sql += ' LIMIT 50';
else if (parseInt(m[1], 10) > 50) sql = sql.replace(/LIMIT\s+\d+/i, 'LIMIT 50');
return [{ json: { valid: true, sql, used, reason: '', audit_sql: aq(true, sql, 0, '') } }];

const v = $('Validate Shop SQL').first().json;
const prep = $('Prep').first().json;
const r = $('Route SQL').first().json;
const esc = (s) => (s || '').toString().replace(/'/g, "''");
const ms = Date.now() - (r.t0 || Date.now());
let rows = [];
try { rows = $('Run Shop SQL').all().map(x => x.json).filter(x => x && typeof x === 'object' && !x.error && Object.keys(x).length > 0).slice(0, 50); } catch(e) {}
const fmtN = (n) => Number(n || 0).toLocaleString('en-US');
const fmtV = (x) => (x === null || x === undefined) ? '-' : String(x).slice(0, 120);
const maskPhone = (s) => String(s || '').replace(/(0\d)(\d+)(\d{3})/, (m, a, b, c) => a + 'X'.repeat(Math.min(b.length, 6)) + c);
const maskAddr = (s) => { s = String(s || ''); return s.length > 14 ? s.slice(0, 6) + '…' + s.slice(-8) : s; };
const masked = rows.map(row => {
  const o = {}; Object.keys(row).slice(0, 10).forEach(k => { o[k] = row[k]; });
  if (o.cust_phone) o.cust_phone = maskPhone(o.cust_phone);
  if (o.address) o.address = maskAddr(o.address);
  if (o.image_url) o.image_url_display = "รูป: " + o.image_url;
  return o;
});
const allImageUrls = rows.filter(function(r){ return r && r.image_url; }).map(function(r){ return r.image_url; }).slice(0, 5);
const lines = masked.map((o, i) => '(' + (i+1) + ') ' + Object.keys(o).map(k => k + '=' + fmtV(o[k])).join(', '));
const d = new Date(); const hh = String(d.getHours()).padStart(2, '0'), mm = String(d.getMinutes()).padStart(2, '0');
const block = rows.length ? ('【ข้อมูลสดจากฐานข้อมูลร้าน (' + hh + ':' + mm + ')】\n' + lines.slice(0, 8).join('\n') + (lines.length > 8 ? '\n… (แสดง 8 จาก ' + lines.length + ' แถว)' : '')) : '';
let answer = '';
if ((r.kind === 'lookup' || r.kind === 'both') && rows.length) {
  const used = v.used || [];
  if (used.indexOf('shop_orders') >= 0) {
    const o = rows[0];
    answer = `ออเดอร์ ${o.code} สถานะ ${o.status || '-'} ยอด ${fmtN(o.total)} บาท`;
    const items = rows.filter(x => x.name).map(x => `• ${x.name} x${x.qty} = ${fmtN(x.price * x.qty)} บาท`);
    if (items.length) answer += '\n' + items.join('\n');
  } else if (rows.length === 1) {
    const p = rows[0];
    answer = `${p.name} ราคา ${fmtN(p.price)} บาท` + (p.old_price > p.price ? ` (ปกติ ${fmtN(p.old_price)})` : '') + ` ร้าน ${p.shop_name || '-'} สต็อก ${fmtN(p.stock)} ชิ้น`;
  } else {
    answer = 'พบ ' + rows.length + ' รายการ:\n' + rows.map(p => `• ${p.name} — ${fmtN(p.price)} บาท (สต็อก ${fmtN(p.stock)})`).join('\n');
  }
}
const src = rows.length ? ['DB สด: ' + (v.used || []).join(',') + ' (' + rows.length + ' แถว)'] : [];
const q1 = esc(prep.userId), q2 = esc((prep.text || '').slice(0, 500));
const q3 = (r.kind || 'rag'), q4 = esc((v.sql || '').slice(0, 2000));
const q5 = rows.length ? 'TRUE' : 'FALSE', q6 = rows.length ? '' : 'run-empty';
const audit_sql = "INSERT INTO ai_sql_audit(channel,user_ref,question,route,sql,rows,ms,ok,err) VALUES ('shop','" + q1 + "','" + q2 + "','" + q3 + "','" + q4 + "'," + rows.length + "," + ms + "," + q5 + ",'" + q6 + "') RETURNING id";
return [{ json: { shaped: true, kind: r.kind, sql_ok: rows.length > 0, sql_rows: rows.length, sql_text: block, sql_answer: answer, sql_sources: src, image_urls: (typeof allImageUrls !== "undefined" ? allImageUrls : []), audit_sql } }];

const v = $('Validate Shop SQL').first().json;
const r = $('Route SQL').first().json;
return [{ json: { shaped_empty: true, kind: r.kind, reason: (v && v.reason) || 'invalid', audit_sql: (v && v.audit_sql) || '' } }];

let out = { ok: false, kind: 'rag', rows: 0, block: '', answer: '', sources: [], images: [], err: 'rag-only' };
try {
  const s = $('Shape Shop Rows').first().json;
  if (s && s.shaped) out = { ok: !!s.sql_ok, kind: s.kind || 'both', rows: s.sql_rows || 0, block: s.sql_text || '', answer: s.sql_answer || '', sources: s.sql_sources || [], images: s.image_urls || [], err: s.sql_ok ? '' : 'run-empty' };
} catch(e) {}
if (!out.ok && !out.rows) {
  try {
    const v = $('Shape SQL Empty').first().json;
    if (v && v.shaped_empty) out = { ok: false, kind: v.kind || 'both', rows: 0, block: '', answer: '', sources: [], err: v.reason || 'invalid' };
  } catch(e2) {}
}
return [{ json: out }];
